import torch

def make_grad_scaler(device):
    return torch.amp.GradScaler(
        "cuda", enabled=device.type == "cuda",
    )

def noise_prediction_step(
    model, optimizer, scaler, x0, alpha_bar, q_sample_fn,
):
    """Run one step with every project object passed explicitly."""
    model.train()
    optimizer.zero_grad(set_to_none=True)
    t = torch.randint(
        0, len(alpha_bar), (x0.shape[0],), device=x0.device,
    )
    xt, target_noise = q_sample_fn(x0, t, alpha_bar)
    use_amp = x0.device.type == "cuda"
    with torch.autocast(
        device_type=x0.device.type, dtype=torch.float16, enabled=use_amp,
    ):
        predicted_noise = model(xt, t)
        loss = torch.nn.functional.mse_loss(
            predicted_noise, target_noise,
        )
    scaler.scale(loss).backward()
    scaler.step(optimizer)
    scaler.update()
    return loss.detach()

import torch
import torch.nn.functional as F

def dit_attention(q, k, v, *, dropout_p=0.0, training=False):
    """Attend over image patches; q, k, v are injected tensors."""
    return F.scaled_dot_product_attention(
        q, k, v,
        dropout_p=dropout_p if training else 0.0,
        is_causal=False,
    )

import torch

@torch.inference_mode()
def sample(model, shape, schedule, device, generator=None):
    """Sample with model and schedule supplied by the caller."""
    model.eval()
    x = torch.randn(shape, device=device, generator=generator)
    for step in reversed(range(schedule.steps)):
        t = torch.full(
            (shape[0],), step, device=device, dtype=torch.long,
        )
        predicted_noise = model(x, t)
        x = schedule.reverse_step(
            x, t, predicted_noise, generator=generator,
        )
    return x
